ORIGINS = ((0, 0), (0, 1), (1, 0), (1, 1))
CHART_INDEX = {origin: k for k, origin in enumerate(ORIGINS)}
HEALING_WEIGHTS = b145.HEALING_WEIGHTS          # (0, 0, 1/2, -1/3), per chart
EX = b105.EX
ET = b105.ET
SX = sp.Symbol("s_x", real=True)
ST = sp.Symbol("s_t", real=True)
