class Fixture:
    """The committed Dirac-Kahler antiperiodic fixture at a general size."""

    def __init__(self, cover_t: int, lx: int, tag: str) -> None:
        self.tag = tag
        self.COVER_T = cover_t
        self.LX = lx
        self.PHYS_T = cover_t // 2
        self.SIZE = cover_t * lx
        self.PHYS = self.PHYS_T * lx
        self.NCELLS = self.SIZE // 4
        self.CELLS = tuple(
            (t, x) for t in range(self.PHYS_T) for x in range(lx)
        )
        self.NU = {c: sp.Symbol(f"n_{c[0]}_{c[1]}", real=True)
                   for c in self.CELLS}
        self.A = {c: sp.Symbol(f"a_{c[0]}_{c[1]}", real=True)
                  for c in self.CELLS}
        self.B = {c: sp.Symbol(f"b_{c[0]}_{c[1]}", real=True)
                  for c in self.CELLS}
        self.MU = {c: sp.Symbol(f"u_{c[0]}_{c[1]}", real=True)
                   for c in self.CELLS}
        self.SHEARS = frozenset(self.B[c] for c in self.CELLS)
        self.EDGE_KEYS = tuple(
            (CHART_INDEX[a], CHART_INDEX[b]) for a in ORIGINS for b in ORIGINS
        )
        self._build_connection()
        self.H_free = self.cover_hodge(self.NU, self.A, self.B, self.MU)
        self._build_reflections()

    # -- geometry ---------------------------------------------------------
    def cover_index(self, t: int, x: int) -> int:
        return (t % self.COVER_T) * self.LX + (x % self.LX)

    def cell_sites(self, t: int, x: int) -> tuple:
        """The four cover sites of the 2x2 cell anchored at (t, x)."""
        return tuple(
            self.cover_index(t + dt, x + dx)
            for dt, dx in ((0, 0), (0, 1), (1, 0), (1, 1))
        )

    def chart_cells(self, origin: tuple) -> tuple:
        return tuple(
            (2 * ct + origin[0], 2 * cx + origin[1])
            for ct in range(self.COVER_T // 2)
            for cx in range(self.LX // 2)
        )

    # -- the connection ---------------------------------------------------
    def _build_connection(self) -> None:
        local = sp.I * (SX * EX + ST * ET)
        rt, rx = b105.shift_lifts()
        self.d = {}
        for origin in ORIGINS:
            gauge = (rt ** origin[0]) * (rx ** origin[1])
            block = sp.expand(gauge.H * local * gauge)
            out: dict = {}
            for anchor in self.chart_cells(origin):
                sites = self.cell_sites(*anchor)
                for p in range(4):
                    for q in range(4):
                        if block[p, q] != 0:
                            key = (sites[p], sites[q])
                            out[key] = out.get(key, 0) + block[p, q]
            self.d[origin] = sclean(out)
        self.star = sadd(self.d[(0, 0)], sscale(self.d[(1, 0)], -1))
        self.edge_d = {
            (CHART_INDEX[a], CHART_INDEX[b]): sadd(
                self.d[a],
                sscale(
                    self.star,
                    HEALING_WEIGHTS[CHART_INDEX[b]]
                    - HEALING_WEIGHTS[CHART_INDEX[a]],
                ),
            )
            for a in ORIGINS
            for b in ORIGINS
        }

    # -- the carrier Hodge ------------------------------------------------
    def cover_hodge(self, nu, a, b, mu) -> dict:
        out: dict = {}

        def bump(i, j, value):
            out[(i, j)] = out.get((i, j), 0) + value

        for t in range(self.COVER_T):
            for x in range(self.LX):
                cell = (t % self.PHYS_T, x)
                s00, s01, s10, s11 = self.cell_sites(t, x)
                bump(s00, s00, nu[cell] / 4)
                bump(s01, s01, a[cell] / 4)
                bump(s10, s10, a[cell] / 4)
                bump(s11, s11, mu[cell] / 4)
                bump(s01, s10, b[cell] / 4)
                bump(s10, s01, b[cell] / 4)
        return sclean(out)

    def flat_moduli(self) -> tuple:
        one = sp.Integer(1)
        return (
            {c: one for c in self.CELLS},
            {c: one for c in self.CELLS},
            {c: sp.Integer(0) for c in self.CELLS},
            {c: one for c in self.CELLS},
        )

    def moduli_from_field(self, field: dict) -> tuple:
        """The committed modulus map, built STRICTLY from sympy exacts.

        The inherited b145.moduli_from_field leaks a Python float when handed a
        plain-int carrier; every carrier here goes through sympify first, and
        the exactness gate measures the result.
        """
        nu, a, b, mu = {}, {}, {}, {}
        for cell, (shear, volume) in field.items():
            shear = sp.sympify(shear)
            volume = sp.sympify(volume)
            nu[cell] = volume
            a[cell] = volume / (1 - shear ** 2)
            b[cell] = -volume * shear / (1 - shear ** 2)
            mu[cell] = 1 / volume
        return nu, a, b, mu

    # -- the antiperiodic quotient ---------------------------------------
    def quotient(self, matrix: dict) -> dict:
        n = self.PHYS
        out: dict = {}
        for (i, j), value in matrix.items():
            if i < n:
                continue
            if j >= n:
                out[(i - n, j - n)] = out.get((i - n, j - n), 0) + value
            else:
                out[(i - n, j)] = out.get((i - n, j), 0) - value
        return sclean(out)

    def quotient_connection(self, differential: dict, hodge: dict) -> dict:
        return self.quotient(
            sscale(
                sadd(smul(hodge, differential),
                     smul(sdagger(differential), hodge)),
                sp.I,
            )
        )

    def quotient_action(self, differential: dict, hodge: dict, mass) -> dict:
        return sadd(
            sscale(self.quotient(hodge), mass),
            self.quotient_connection(differential, hodge),
        )

    # -- the staggered parity --------------------------------------------
    def parity(self) -> dict:
        return {
            (k, k): sp.Integer((-1) ** (k // self.LX + k % self.LX))
            for k in range(self.PHYS)
        }

    # -- reflections ------------------------------------------------------
    def lift_sign(self, t: int) -> int:
        return -1 if (t // self.PHYS_T) % 2 == 0 else 1

    def descent(self, label: tuple) -> dict:
        """(r phi)(a, x) = sigma(a) phi(p_t - a, e_x (x - p_x)), exact ints."""
        _et, pt, ex, px = label
        out: dict = {}
        for a in range(self.PHYS_T):
            b = (pt - a) % self.PHYS_T
            sign = self.lift_sign(a) * self.lift_sign(pt - a)
            for x in range(self.LX):
                y = (ex * (x - px)) % self.LX
                out[(self.LX * a + x, self.LX * b + y)] = sp.Integer(sign)
        return out

    def _build_reflections(self) -> None:
        self.site_labels = tuple(
            (-1, pt, ex, px)
            for pt in range(0, self.COVER_T, 2)
            for ex in (1, -1)
            for px in range(self.LX)
        )
        self.link_labels = tuple(
            (-1, pt, ex, px)
            for pt in range(1, self.COVER_T, 2)
            for ex in (1, -1)
            for px in range(self.LX)
        )
        self.involutive = tuple(
            lab for lab in self.site_labels
            if self._is_involutive(self.descent(lab))
        )
        self.x_trivial = tuple(
            lab for lab in self.involutive if lab[2] == 1 and lab[3] == 0
        )
        self.non_x_trivial = tuple(
            lab for lab in self.involutive if lab not in set(self.x_trivial)
        )

    def _is_involutive(self, r: dict) -> bool:
        square = smul(r, r)
        identity = {(k, k): sp.Integer(1) for k in range(self.PHYS)}
        return sadd(square, sscale(identity, -1)) == {}

    def fixed_slice(self, label: tuple) -> int:
        return (label[1] // 2) % self.PHYS_T

    def slice_rows(self, *slices: int) -> tuple:
        return tuple(
            self.LX * (s % self.PHYS_T) + x
            for s in slices for x in range(self.LX)
        )

    def pairing(self, reflection: dict, action: dict, rows: tuple) -> sp.Matrix:
        """[r Q]_{S,S} = herm(Sel^T r Q Sel), the committed law."""
        index = {row: k for k, row in enumerate(rows)}
        product = smul(reflection, action)
        n = len(rows)
        out = sp.zeros(n, n)
        for (i, j), value in product.items():
            if i in index and j in index:
                out[index[i], index[j]] = value
        return sp.expand((out + out.H) / 2)

    # -- the region, from its own definition ------------------------------
    def pinned_cells(self, c: int) -> frozenset:
        """The sigma coordinates the region pins: the two links incident to c.

        ENUMERATED, not counted by formula -- this is the measurement the solve
        transcript's tautological gate skipped.
        """
        return frozenset(
            {((c - 1) % self.PHYS_T, x) for x in range(self.LX)}
            | {(c % self.PHYS_T, x) for x in range(self.LX)}
        )

    def free_cells(self, c: int) -> frozenset:
        return frozenset(set(self.CELLS) - self.pinned_cells(c))

    def region_substitution(self, c: int) -> dict:
        pin: dict = {}
        for cell in self.pinned_cells(c):
            pin[self.B[cell]] = sp.Integer(0)
            pin[self.A[cell]] = self.NU[cell]
        return pin


# ---------------------------------------------------------------------------
# helpers on symbolic blocks
# ---------------------------------------------------------------------------
def free_symbols_of(matrix: sp.MatrixBase) -> set:
    out: set = set()
    for entry in matrix:
        out |= sp.expand(entry).free_symbols
    return out


def is_linear_homogeneous_in(matrix: sp.MatrixBase, variables) -> bool:
    variables = list(variables)
    if not variables:
        return all(sp.expand(e) == 0 for e in matrix)
    zeroed = {v: 0 for v in variables}
    if any(sp.expand(e).subs(zeroed) != 0 for e in matrix):
        return False
    for entry in matrix:
        entry = sp.expand(entry)
        if entry == 0:
            continue
        if sp.Poly(entry, *variables).total_degree() > 1:
            return False
    return True


LAM = sp.Symbol("lam")


def real_symmetric_inertia(matrix: sp.MatrixBase) -> tuple:
    """Exact (n_positive, n_negative, n_zero) via Descartes on the charpoly.

    A Hermitian matrix has a real-rooted characteristic polynomial, and for a
    real-rooted polynomial Descartes' rule is an EQUALITY, so the sign-change
    count of the coefficient sequence is exactly the number of positive roots.

    NO sympy.nsimplify.  The solve transcript's routine called it on these
    coefficients -- exactly the corruption Block 164 flagged for the repo -- and
    it is STRUCK here: the characteristic polynomial of an exact rational matrix
    already has exact Rational coefficients.
    """
    n = matrix.rows
    poly = sp.Poly(matrix.charpoly(LAM).as_expr(), LAM)
    coeffs = list(poly.all_coeffs())

    def changes(seq):
        seq = [c for c in seq if c != 0]
        return sum(1 for k in range(len(seq) - 1) if seq[k] * seq[k + 1] < 0)

    positive = changes(coeffs)
    alt = [c * (-1) ** k for k, c in enumerate(reversed(coeffs))]
    negative = changes(list(reversed(alt)))
    return positive, negative, n - positive - negative


def inertia_self_test() -> int:
    """Descartes-on-charpoly against sympy's own exact root count."""
    cases = (
        sp.diag(1, 2, 3),
        sp.diag(-1, -R(1, 2)),
        sp.diag(0, 1, -1),
        sp.Matrix([[0, 1], [1, 0]]),
        sp.Matrix([[2, 1], [1, 2]]),
        sp.Matrix([[R(1, 3), R(2, 5)], [R(2, 5), R(1, 7)]]),
        sp.zeros(3, 3),
        sp.Matrix([[1, 2, 0], [2, 1, 0], [0, 0, R(-3, 4)]]),
    )
    agree = 0
    for case in cases:
        mine = real_symmetric_inertia(case)
        roots = sp.roots(case.charpoly(LAM).as_expr(), LAM)
        reference = (
            sum(m for r, m in roots.items() if r > 0),
            sum(m for r, m in roots.items() if r < 0),
            sum(m for r, m in roots.items() if r == 0),
        )
        agree += int(mine == reference)
    return agree


# ---------------------------------------------------------------------------
# the per-fixture probe.  `edges` and `nonx_edges` are the SAMPLE, disclosed.
# ---------------------------------------------------------------------------
def probe_fixture(fx: Fixture, edges: tuple, nonx_edges: tuple) -> dict:
    out: dict = {}
    exact: list = []

    # -- the fixture is well formed at this size --------------------------
    tiles = len(fx.chart_cells((0, 0))) == fx.NCELLS and all(
        len(set(fx.chart_cells(o))) == fx.NCELLS for o in ORIGINS
    )
    covered = all(
        len(set(itertools.chain.from_iterable(
            fx.cell_sites(*a) for a in fx.chart_cells(o)))) == fx.SIZE
        for o in ORIGINS
    )
    out["tiles"] = bool(tiles and covered)
    out["involutive"] = len(fx.involutive)
    out["x_trivial"] = len(fx.x_trivial)
    out["non_x_trivial"] = len(fx.non_x_trivial)
    # the checker's closed form, tested rather than assumed
    out["count_law"] = bool(
        len(fx.involutive) == fx.PHYS_T * (fx.LX + 2)
        and len(fx.x_trivial) == fx.PHYS_T
    )
    out["edges_used"] = len(edges)
    out["nonx_edges_used"] = len(nonx_edges)

    hq = fx.quotient(fx.H_free)
    hq_dense = dense(hq, fx.PHYS, fx.PHYS)
    parity = dense(fx.parity(), fx.PHYS, fx.PHYS)
    zero_phys = sp.zeros(fx.PHYS, fx.PHYS)
    exact.append(hq_dense)

    # -- P1: the grading identities ---------------------------------------
    out["parity_commutes"] = bool(
        sp.expand(parity * hq_dense * parity - hq_dense) == zero_phys
    )
    anti = 0
    for key in edges:
        k_matrix = dense(
            fx.quotient_connection(fx.edge_d[key], fx.H_free), fx.PHYS, fx.PHYS
        )
        if sp.expand(parity * k_matrix * parity + k_matrix) == zero_phys:
            anti += 1
    out["parity_anticommutes"] = anti
    graded = 0
    all_labels = fx.site_labels + fx.link_labels
    for lab in all_labels:
        r = dense(fx.descent(lab), fx.PHYS, fx.PHYS)
        sign = (-1) ** (lab[1] + lab[3])
        if sp.expand(r * parity * r.T - sign * parity) == zero_phys:
            graded += 1
    out["graded_labels"] = graded
    out["all_labels"] = len(all_labels)

    # -- P2: the diagonality theorem --------------------------------------
    displacements = {
        (j // fx.LX - i // fx.LX) % fx.PHYS_T for (i, j) in hq
    }
    out["displacements"] = tuple(sorted(displacements))
    out["displacement_allowed"] = bool(
        displacements <= {0, 1, (fx.PHYS_T - 1) % fx.PHYS_T}
    )
    out["distance_two_present"] = bool(2 % fx.PHYS_T in displacements)
    flat = dense(fx.quotient(fx.cover_hodge(*fx.flat_moduli())),
                 fx.PHYS, fx.PHYS)
    out["flat_diagonal"] = bool(flat.is_diagonal())
    shear_zero = {v: 0 for v in fx.SHEARS}
    out["shear_carries_offdiagonal"] = bool(all(
        sp.expand(hq_dense[i, j].subs(shear_zero)) == 0
        for i in range(fx.PHYS) for j in range(fx.PHYS) if i != j
    ))

    # -- P3: the criterion at s_t = 0 --------------------------------------
    d_trace = {
        (t, x): (
            fx.NU[(t, x)]
            + fx.A[((t - 1) % fx.PHYS_T, x)]
            + fx.A[(t, (x - 1) % fx.LX)]
            + fx.MU[((t - 1) % fx.PHYS_T, (x - 1) % fx.LX)]
        ) / 4
        for (t, x) in fx.CELLS
    }
    zero_t = {ST: 0}
    q_zero: dict = {}
    q_full: dict = {}
    for key in edges:
        action = fx.quotient_action(fx.edge_d[key], fx.H_free, MASS)
        q_full[key] = action
        q_zero[key] = sclean({k: v.subs(zero_t) for k, v in action.items()})

    n = fx.LX
    zero_block = sp.zeros(n, n)
    p3_cells = 0
    hollow = 0
    b_shear_free = 0
    c_local = 0
    mass_identity = 0
    c_support_by_label: dict = {}
    two_cycle_slots = 0
    two_cycle_traceless = 0
    two_cycle_massive = 0
    for key in edges:
        for lab in fx.involutive:
            c = fx.fixed_slice(lab)
            rows = fx.slice_rows(c, c + 1)
            pairing = fx.pairing(fx.descent(lab), q_zero[key], rows)
            b_block = pairing[:n, :n]
            c_block = pairing[:n, n:]
            corner = pairing[n:, n:]
            p3_cells += 1
            hollow += int(sp.expand(corner) == zero_block)
            b_shear_free += int(not (free_symbols_of(b_block) & fx.SHEARS))
            local = [fx.B[cell] for cell in sorted(fx.pinned_cells(c))]
            outside = free_symbols_of(c_block) & (fx.SHEARS - set(local))
            c_local += int(
                not outside and is_linear_homogeneous_in(c_block, local)
            )
            if lab in fx.x_trivial:
                # PER LABEL, never unioned across fixed slices: the region is
                # cut one fixed slice at a time, so its codimension is the
                # support of ONE label's C-form, not of all of them together.
                c_support_by_label.setdefault(lab, set()).update(
                    cell for cell in fx.CELLS
                    if fx.B[cell] in free_symbols_of(c_block)
                )
            ex, px = lab[2], lab[3]
            want = sp.zeros(n, n)
            for x in range(fx.LX):
                y = (ex * (x - px)) % fx.LX
                want[x, y] = MASS * (d_trace[(c, x)] + d_trace[(c, y)]) / 2
            mass_identity += int(
                sp.expand(b_block.subs({SX: 0}) - want) == zero_block
            )
            pi = {x: (ex * (x - px)) % fx.LX for x in range(fx.LX)}
            for x in range(fx.LX):
                y = pi[x]
                if y == x or x > y:
                    continue
                two_cycle_slots += 1
                minor = sp.Matrix([[b_block[x, x], b_block[x, y]],
                                   [b_block[y, x], b_block[y, y]]])
                two_cycle_traceless += int(sp.expand(sp.trace(minor)) == 0)
                two_cycle_massive += int(
                    sp.expand(minor[0, 1].coeff(MASS, 1)) != 0
                )
    out["p3_cells"] = p3_cells
    out["hollow"] = hollow
    out["b_shear_free"] = b_shear_free
    out["c_local"] = c_local
    out["mass_identity"] = mass_identity
    out["two_cycle"] = (two_cycle_slots, two_cycle_traceless,
                        two_cycle_massive)

    # THE DERIVATION the solve's tautology skipped: enumerate the cone, then
    # enumerate the pinned coordinates from the region's own definition, then
    # require the MEASURED C-support to be exactly that set.
    out["ambient"] = 2 * len(fx.CELLS)
    pinned_sizes = {len(fx.pinned_cells(c)) for c in range(fx.PHYS_T)}
    out["pinned_sizes"] = tuple(sorted(pinned_sizes))
    out["pinned"] = min(pinned_sizes)
    out["region_dim"] = out["ambient"] - out["pinned"]
    support_sizes = {len(cells) for cells in c_support_by_label.values()}
    out["c_support"] = max(support_sizes)
    out["c_support_uniform"] = len(support_sizes) == 1
    out["c_support_is_pinned_set"] = bool(
        c_support_by_label
        and all(
            cells == set(fx.pinned_cells(fx.fixed_slice(lab)))
            for lab, cells in c_support_by_label.items()
        )
    )

    # the region normal form: m diag(D) (+) 0, s_x-free and edge-free
    x_lab = fx.x_trivial[0]
    c0 = fx.fixed_slice(x_lab)
    pin0 = fx.region_substitution(c0)
    normal = 0
    reference = None
    edge_blind = 0
    for key in edges:
        pairing = sp.expand(
            fx.pairing(fx.descent(x_lab), q_zero[key],
                       fx.slice_rows(c0, c0 + 1)).subs(pin0)
        )
        want = sp.zeros(2 * n, 2 * n)
        for x in range(fx.LX):
            want[x, x] = MASS * sp.expand(d_trace[(c0, x)].subs(pin0))
        normal += int(sp.expand(pairing - want) == sp.zeros(2 * n, 2 * n))
        if reference is None:
            reference = pairing
            edge_blind += 1
        else:
            edge_blind += int(
                sp.expand(pairing - reference) == sp.zeros(2 * n, 2 * n)
            )
        exact.append(pairing)
    out["region_normal"] = normal
    out["edge_blind"] = edge_blind

    # -- P4a: affine-linearity, structural --------------------------------
    bihomogeneous = 0
    entries = 0
    for key in fx.EDGE_KEYS:
        for value in fx.edge_d[key].values():
            entries += 1
            poly = sp.Poly(sp.expand(value / sp.I), ST, SX)
            bihomogeneous += int(
                set(poly.monoms()) <= {(0, 1), (1, 0)}
            )
    out["bihomogeneous"] = (bihomogeneous, entries)
    st_degree = 0
    for key in edges[:2]:
        for lab in fx.x_trivial:
            cc = fx.fixed_slice(lab)
            pairing = fx.pairing(fx.descent(lab), q_full[key],
                                 fx.slice_rows(cc, cc + 1))
            for entry in pairing:
                entry = sp.expand(entry)
                if entry == 0:
                    continue
                st_degree = max(st_degree, sp.Poly(entry, ST).total_degree())
    out["max_st_degree"] = st_degree

    # -- THE WRAP ARTIFACT: the distance-2 content law ---------------------
    def shear_slices_between(action: dict, r0: int, c1: int) -> set:
        rows = [fx.LX * (r0 % fx.PHYS_T) + x for x in range(fx.LX)]
        cols = [fx.LX * (c1 % fx.PHYS_T) + x for x in range(fx.LX)]
        syms: set = set()
        for i in rows:
            for j in cols:
                syms |= sp.expand(action.get((i, j), 0)).free_symbols
        return {t for (t, x) in fx.CELLS if fx.B[(t, x)] in syms}

    collapse = (2 % fx.PHYS_T) == ((-2) % fx.PHYS_T)
    out["collapse"] = bool(collapse)
    leak = 0
    pairs = 0
    within = 0
    content: dict = {}
    odd_nonempty = 0
    even_empty = 0
    for key in edges:
        action = q_full[key]
        for cc in range(fx.PHYS_T):
            got = shear_slices_between(action, cc - 1, cc + 1)
            if cc % 2 == 1:
                pin_set = {(cc - 1) % fx.PHYS_T, cc % fx.PHYS_T}
                free_set = {(cc + 1) % fx.PHYS_T, (cc + 2) % fx.PHYS_T}
                pairs += 1
                leak += int(not got <= pin_set)
                within += int(got <= (pin_set | free_set))
                content.setdefault(cc, set()).update(got)
                odd_nonempty += int(bool(got))
            else:
                even_empty += int(not got)
    out["leak"] = leak
    out["leak_pairs"] = pairs
    out["within_union"] = within
    out["dist2_content"] = {cc: tuple(sorted(v)) for cc, v in
                            sorted(content.items())}
    out["odd_nonempty"] = odd_nonempty
    out["even_empty"] = even_empty
    out["odd_slices"] = len(range(1, fx.PHYS_T, 2))
    # THE VACUITY, measured: mod 4 the containment set is the whole lattice
    out["p5d_union_is_everything"] = bool(all(
        {(cc - 1) % fx.PHYS_T, cc % fx.PHYS_T,
         (cc + 1) % fx.PHYS_T, (cc + 2) % fx.PHYS_T}
        == set(range(fx.PHYS_T))
        for cc in range(1, fx.PHYS_T, 2)
    ))

    # -- the corner E and the C-branch on the region -----------------------
    def region_branches(labels: tuple, keys: tuple) -> dict:
        cells = 0
        e_live = 0
        e_traceless = 0
        e_pure = 0
        c_live = 0
        e_slices: set = set()
        e_width = 0
        by_slice: dict = {}
        c_by_slice: dict = {}
        for lab in labels:
            cc = fx.fixed_slice(lab)
            pin = fx.region_substitution(cc)
            free_shears = {fx.B[cell] for cell in fx.free_cells(cc)}
            label_slices: set = set()
            for key in keys:
                pairing = sp.expand(
                    fx.pairing(fx.descent(lab), q_full[key],
                               fx.slice_rows(cc, cc + 1)).subs(pin)
                )
                corner = sp.expand(pairing[n:, n:])
                e_matrix = sp.expand(sp.diff(corner, ST))
                cells += 1
                e_traceless += int(
                    sp.expand(corner - ST * e_matrix) == zero_block
                    and sp.expand(sp.trace(e_matrix)) == 0
                )
                syms = free_symbols_of(e_matrix)
                e_pure += int(not (syms - free_shears))
                hit = {t for (t, x) in fx.CELLS if fx.B[(t, x)] in syms}
                e_slices |= hit
                label_slices |= hit
                live = int(sp.expand(e_matrix) != zero_block)
                e_live += live
                by_slice[cc] = by_slice.get(cc, 0) + live
                c_derivative = sp.expand(sp.diff(pairing[:n, n:], ST))
                c_hit = int(c_derivative != zero_block)
                c_live += c_hit
                c_by_slice[cc] = c_by_slice.get(cc, 0) + c_hit
            e_width = max(e_width, len(label_slices))
        return {
            "cells": cells, "e_live": e_live, "e_traceless": e_traceless,
            "e_pure": e_pure, "c_live": c_live, "e_width": e_width,
            "e_slices": tuple(sorted(e_slices)),
            "e_by_slice": dict(sorted(by_slice.items())),
            "c_by_slice": dict(sorted(c_by_slice.items())),
        }

    out["xt"] = region_branches(fx.x_trivial, edges)
    out["nonxt"] = region_branches(fx.non_x_trivial, nonx_edges)
    # THE E/C CODIMENSION SPLIT, corrected against the measurement.  The
    # checker's wording -- "the E-branch needs codimension L_x" -- does not
    # survive a full edge sweep: measured over every healed edge, E's per-label
    # shear support is BOTH free link slices, not one.  What IS true, and is
    # what the codimension argument actually needs, is that the two supports are
    # DISJOINT: C is a form in exactly the 2 L_x shears the region PINS, and E
    # is a pure form in the shears the region leaves FREE.  So E lives entirely
    # in the region's own free directions and contributes ZERO codimension; the
    # region's 2 L_x is the C-branch's alone.  The width is reported as a
    # measurement and is sample-sensitive; the disjointness is not.
    out["e_free_only"] = bool(
        out["xt"]["e_pure"] == out["xt"]["cells"]
        and out["nonxt"]["e_pure"] == out["nonxt"]["cells"]
    )
    out["e_slice_width"] = out["xt"]["e_width"]

    # -- THE COMPLEMENTARITY, direct, on explicit curved region carriers ----
    def volume(t, x):
        return R(1 + (3 * t + 5 * x) % 5, 3) + R(1, 2)

    psd_at_zero = 0
    zero_cells = 0
    not_psd = 0
    st_cells = 0
    ranks: set = set()
    comp_edges = (fx.EDGE_KEYS[0], fx.EDGE_KEYS[11])
    for lab in fx.x_trivial:
        cc = fx.fixed_slice(lab)
        pinned = {t for (t, x) in fx.pinned_cells(cc)}
        field = {
            (t, x): (sp.Integer(0) if t in pinned else R(2, 5), volume(t, x))
            for (t, x) in fx.CELLS
        }
        hodge = fx.cover_hodge(*fx.moduli_from_field(field))
        for key in comp_edges:
            action = fx.quotient_action(fx.edge_d[key], hodge, MASS)
            for st_value in (sp.Integer(0),) + PROBE_ST:
                evaluated = sclean({
                    k: sp.expand(v.subs({ST: st_value, SX: ATLAS_SX,
                                         MASS: sp.Integer(1)}))
                    for k, v in action.items()
                })
                pairing = fx.pairing(fx.descent(lab), evaluated,
                                     fx.slice_rows(cc, cc + 1))
                exact.append(pairing)
                inertia = real_symmetric_inertia(pairing)
                if st_value == 0:
                    zero_cells += 1
                    psd_at_zero += int(
                        inertia[1] == 0 and inertia[0] == fx.LX
                    )
                    ranks.add(inertia[0])
                else:
                    st_cells += 1
                    not_psd += int(inertia[1] > 0)
    out["complementarity"] = (psd_at_zero, zero_cells, not_psd, st_cells)
    out["region_rank"] = tuple(sorted(ranks))

    # -- the criterion vs DIRECT exact inertia -----------------------------
    carriers = (
        ("flat", {(t, x): (sp.Integer(0), sp.Integer(1)) for (t, x) in fx.CELLS}),
        ("graded nu", {(t, x): (sp.Integer(0), R(1 + t + x, 2))
                       for (t, x) in fx.CELLS}),
        ("far shear only",
         {(t, x): (R(1, 2) if t in (2, 3) else sp.Integer(0),
                   R(1 + (t + x) % 3, 2)) for (t, x) in fx.CELLS}),
    )
    masses = (R(1, 3), -R(1, 3))
    bench_edges = edges[:2]
    agree = 0
    disagree = 0
    bench_psd = 0
    for _name, field in carriers:
        hodge = fx.cover_hodge(*fx.moduli_from_field(field))
        for key in bench_edges:
            for mass in masses:
                action = sclean({
                    k: sp.expand(v.subs({ST: 0, SX: ATLAS_SX}))
                    for k, v in fx.quotient_action(
                        fx.edge_d[key], hodge, mass).items()
                })
                for lab in fx.involutive:
                    cc = fx.fixed_slice(lab)
                    pairing = fx.pairing(fx.descent(lab), action,
                                         fx.slice_rows(cc, cc + 1))
                    inertia = real_symmetric_inertia(pairing)
                    measured = inertia[1] == 0 and inertia[0] == fx.LX
                    predicted = (
                        (lab[2], lab[3]) == (1, 0)
                        and mass > 0
                        and all(field[cell][0] == 0
                                for cell in fx.pinned_cells(cc))
                    )
                    agree += int(measured == predicted)
                    disagree += int(measured != predicted)
                    bench_psd += int(measured)
    out["bench"] = (agree + disagree, agree, disagree, bench_psd)
    out["bench_shape"] = (len(carriers), len(bench_edges), len(masses),
                          len(fx.involutive))

    out["exact"] = all(no_float(item) for item in exact)
    return out


