@dataclass(frozen=True)
class Facts:
    main_head: str
    authority: AuthorityCertificate
    anchors: tuple          # B: the rebuild is the committed construction
    grading: tuple          # C: P1/P2, the grading identities
    law: tuple              # D: P3 and the DERIVED dimension law
    branch: tuple           # E: affine-linearity, C-branch, complementarity
    wrap: tuple             # F: the wrap-artifact theorem at three points
    parity: tuple           # G: the odd-slice support and the P5d vacuity
    deep: bool
    exact_no_float: bool
    b164_already_scoped: bool
    scope: dict


def anchor_certificate(fx: Fixture) -> tuple:
    """A0-A6: the from-scratch 8x4 rebuild IS the committed construction."""
    results = []
    results.append(
        (fx.SIZE, fx.PHYS, fx.NCELLS, fx.PHYS_T, fx.LX)
        == (b145.SIZE, b145.PHYS, 8, b145.PHYS_T, b145.LX)
    )
    landed_d, landed_star = b145.connection(SX, ST)
    landed_edge = b145.edge_differentials(landed_d, landed_star,
                                          HEALING_WEIGHTS)
    results.append(all(
        sp.expand(dense(fx.edge_d[key], fx.SIZE, fx.SIZE) - landed_edge[key])
        == sp.zeros(fx.SIZE, fx.SIZE)
        for key in fx.EDGE_KEYS
    ))
    substitution = {}
    for cell in fx.CELLS:
        substitution[fx.NU[cell]] = b145.NU_MODULUS[cell]
        substitution[fx.A[cell]] = b145.A_MODULUS[cell]
        substitution[fx.B[cell]] = b145.B_MODULUS[cell]
        substitution[fx.MU[cell]] = b145.INV_MODULUS[cell]
    landed_hodge = b145.cover_hodge_general(
        b145.NU_MODULUS, b145.A_MODULUS, b145.B_MODULUS, b145.INV_MODULUS
    )
    results.append(
        sp.expand(dense(fx.H_free, fx.SIZE, fx.SIZE).subs(substitution)
                  - landed_hodge) == sp.zeros(fx.SIZE, fx.SIZE)
    )
    key = (0, 0)
    mine = dense(
        fx.quotient_action(fx.edge_d[key], fx.H_free, MASS), fx.PHYS, fx.PHYS
    ).subs(substitution).subs({MASS: b145.MASS})
    landed = b145.quotient_action(landed_edge[key], landed_hodge, b145.MASS)
    results.append(sp.expand(mine - landed) == sp.zeros(fx.PHYS, fx.PHYS))
    descent_ok = True
    for lab in fx.site_labels + fx.link_labels:
        landed_descent = b163.DESCENT.get(lab)
        if landed_descent is None:
            descent_ok = False
            break
        if sp.expand(dense(fx.descent(lab), fx.PHYS, fx.PHYS)
                     - landed_descent) != sp.zeros(fx.PHYS, fx.PHYS):
            descent_ok = False
            break
    results.append(descent_ok)
    results.append(
        set(fx.involutive) == set(b163.INVOLUTIVE_SITE)
        and set(fx.x_trivial) == set(b163.X_TRIVIAL)
    )
    results.append(
        sp.expand(dense(fx.parity(), fx.PHYS, fx.PHYS)
                  - b143.staggered_parity()) == sp.zeros(fx.PHYS, fx.PHYS)
    )
    return tuple(results)


