def b164_scope_measurement() -> bool:
    """Does the LANDED Block 164 note already fence the T_phys = 4 artifact?

    Measured on the landed note's own text, not asserted.  If every marker is
    there, the note presents TWO branches, localizes the E-branch as a census at
    its fixture, records the C-branch on every region cell, and fences itself to
    the fixture -- so no correction-in-successor is owed.
    """
    try:
        text = normalized_note(
            (ROOT / BLOCK164_NOTE).read_text(encoding="utf-8")
        )
    except OSError:
        return False
    return all(marker in text for marker in B164_FENCE_MARKERS)


def measure(deep: bool) -> Facts:
    main_head = git_output("rev-parse", "origin/main")
    authority = authority_certificate(main_head)

    fixtures = {tag: Fixture(cover_t, lx, tag)
                for tag, cover_t, lx in FIXTURE_SPECS}
    anchors = anchor_certificate(fixtures["8x4"])

    probes: dict = {}
    for tag, _cover_t, _lx in FIXTURE_SPECS:
        fx = fixtures[tag]
        if deep:
            edges = fx.EDGE_KEYS
            nonx_edges = fx.EDGE_KEYS[:4]
        else:
            edges = fx.EDGE_KEYS[:BASELINE_EDGES]
            nonx_edges = fx.EDGE_KEYS[:BASELINE_NONX_EDGES]
        probes[tag] = probe_fixture(fx, edges, nonx_edges)

    # ------------------------------------------------------------ B ------
    anchors_facts = (
        sum(1 for value in anchors if value),
        len(anchors),
        tuple(probes[tag]["tiles"] for tag in TAGS),
        tuple(probes[tag]["involutive"] for tag in TAGS),
        tuple(probes[tag]["x_trivial"] for tag in TAGS),
        tuple(probes[tag]["count_law"] for tag in TAGS),
        tuple(probes[tag]["edges_used"] for tag in TAGS),
    )

    # ------------------------------------------------------------ C ------
    grading = (
        tuple(probes[tag]["parity_commutes"] for tag in TAGS),
        tuple((probes[tag]["parity_anticommutes"], probes[tag]["edges_used"])
              for tag in TAGS),
        tuple((probes[tag]["graded_labels"], probes[tag]["all_labels"])
              for tag in TAGS),
        {tag: probes[tag]["displacements"] for tag in TAGS},
        tuple(probes[tag]["displacement_allowed"] for tag in TAGS),
        tuple(probes[tag]["distance_two_present"] for tag in TAGS),
        tuple(probes[tag]["flat_diagonal"] for tag in TAGS),
        tuple(probes[tag]["shear_carries_offdiagonal"] for tag in TAGS),
    )

    # ------------------------------------------------------------ D ------
    law = (
        tuple((probes[tag]["hollow"], probes[tag]["p3_cells"])
              for tag in TAGS),
        tuple((probes[tag]["b_shear_free"], probes[tag]["p3_cells"])
              for tag in TAGS),
        tuple((probes[tag]["c_local"], probes[tag]["p3_cells"])
              for tag in TAGS),
        tuple((probes[tag]["mass_identity"], probes[tag]["p3_cells"])
              for tag in TAGS),
        tuple(probes[tag]["two_cycle"] for tag in TAGS),
        {tag: probes[tag]["ambient"] for tag in TAGS},
        {tag: probes[tag]["pinned"] for tag in TAGS},
        {tag: probes[tag]["region_dim"] for tag in TAGS},
        tuple(probes[tag]["c_support"] for tag in TAGS),
        tuple(probes[tag]["c_support_is_pinned_set"]
              and probes[tag]["c_support_uniform"] for tag in TAGS),
        tuple((probes[tag]["region_normal"], probes[tag]["edges_used"])
              for tag in TAGS),
        tuple((probes[tag]["edge_blind"], probes[tag]["edges_used"])
              for tag in TAGS),
        len({(spec[1] // 2, spec[2]) for spec in FIXTURE_SPECS}),
        tuple((probes[tag]["e_free_only"], probes[tag]["e_slice_width"])
              for tag in TAGS),
        tuple(probes[tag]["bench"] for tag in TAGS),
        tuple(probes[tag]["bench_shape"] for tag in TAGS),
    )

    # ------------------------------------------------------------ E ------
    branch = (
        tuple(probes[tag]["bihomogeneous"] for tag in TAGS),
        tuple(probes[tag]["max_st_degree"] for tag in TAGS),
        tuple((probes[tag]["xt"]["c_live"], probes[tag]["xt"]["cells"])
              for tag in TAGS),
        {tag: probes[tag]["xt"]["c_by_slice"] for tag in TAGS},
        tuple(probes[tag]["complementarity"] for tag in TAGS),
        tuple(probes[tag]["region_rank"] for tag in TAGS),
        inertia_self_test(),
    )

    # ------------------------------------------------------------ F ------
    wrap = (
        tuple(probes[tag]["collapse"] for tag in TAGS),
        tuple((probes[tag]["leak"], probes[tag]["leak_pairs"])
              for tag in TAGS),
        {tag: probes[tag]["dist2_content"] for tag in TAGS},
        tuple((probes[tag]["xt"]["e_live"], probes[tag]["xt"]["cells"])
              for tag in TAGS),
        tuple((probes[tag]["xt"]["e_traceless"], probes[tag]["xt"]["cells"])
              for tag in TAGS),
        tuple((probes[tag]["xt"]["e_pure"], probes[tag]["xt"]["cells"])
              for tag in TAGS),
        tuple((probes[tag]["nonxt"]["e_live"], probes[tag]["nonxt"]["cells"])
              for tag in TAGS),
        {tag: probes[tag]["xt"]["e_by_slice"] for tag in TAGS},
        tuple(probes[tag]["xt"]["e_slices"] for tag in TAGS),
    )

    # ------------------------------------------------------------ G ------
    parity_facts = (
        tuple((probes[tag]["odd_nonempty"],
               probes[tag]["odd_slices"] * probes[tag]["edges_used"])
              for tag in TAGS),
        tuple((probes[tag]["even_empty"],
               (probes[tag]["odd_slices"]) * probes[tag]["edges_used"])
              for tag in TAGS),
        tuple((probes[tag]["within_union"], probes[tag]["leak_pairs"])
              for tag in TAGS),
        tuple(probes[tag]["p5d_union_is_everything"] for tag in TAGS),
    )

    return Facts(
        main_head=main_head,
        authority=authority,
        anchors=anchors_facts,
        grading=grading,
        law=law,
        branch=branch,
        wrap=wrap,
        parity=parity_facts,
        deep=deep,
        exact_no_float=all(probes[tag]["exact"] for tag in TAGS),
        b164_already_scoped=b164_scope_measurement(),
        scope=scope_certificate(raw_note()),
    )


