# ---------------------------------------------------------------------------
# claims: the only thing a mutation is allowed to touch
# ---------------------------------------------------------------------------
def build_claims(mutation: str) -> dict:
    claims: dict = {
        "main_head": CURRENT_MAIN,
        "parent_pin": "resolved",
        "anchors_passing": ANCHOR_COUNT,
        "space_obstruction": False,
        "grading_is_universal": True,
        "region_dims": tuple(REGION_DIMS[tag] for tag in TAGS),
        "law_is_a_fit": False,
        "max_st_degree": 1,
        "c_branch_universal": True,
        "e_mechanism_scales": False,
        "leak_by_size": tuple(
            (1 if COLLAPSE[tag] else 0) for tag in TAGS
        ),
        "p5d_binding_everywhere": False,
        "b164_correction_required": False,
        "required_scope_keys": SCOPE_KEYS,
    }
    if mutation == "stale_main_authority":
        claims["main_head"] = STALE_MAIN
    elif mutation == "stale_parent_authority":
        claims["parent_pin"] = "stale"
    elif mutation == "break_rebuild_anchor":
        # THE PIN DENIED: the from-scratch 8x4 rebuild asserted to differ from
        # the committed chain on one anchor, which would strip every
        # larger-cover statement of its warrant
        claims["anchors_passing"] = ANCHOR_COUNT - 1
    elif mutation == "claim_space_obstruction":
        # THE SPACE-GROWTH VERDICT DENIED: L_x = 6 asserted to obstruct the
        # staggered tiling, which the partition measurement forbids
        claims["space_obstruction"] = True
    elif mutation == "break_grading_identity":
        # P1 DENIED: the Z_2 grading asserted to fail at some size, which the
        # full-family commutation and the per-label conjugation forbid
        claims["grading_is_universal"] = False
    elif mutation == "break_scaling_law":
        # THE LAW DENIED at one point: 16x4's region asserted to have the same
        # dimension as 12x4's, which the enumerated cone and pinned set forbid
        claims["region_dims"] = tuple(
            40 if tag == "16x4" else REGION_DIMS[tag] for tag in TAGS
        )
    elif mutation == "claim_law_fitted":
        # THE SOLVE'S TAUTOLOGY RE-INTRODUCED: the dimension law asserted to
        # rest on a three-point fit rather than a per-size derivation, which
        # the enumerated codimension and the FOURTH size point deny
        claims["law_is_a_fit"] = True
    elif mutation == "break_affine_linearity":
        # the exactness result denied: P asserted to carry s_t^2 content, which
        # would put the exclusion back into a perturbative census
        claims["max_st_degree"] = 2
    elif mutation == "break_c_branch":
        # THE SIZE-INDEPENDENT OBSTRUCTION DENIED: dC/ds_t asserted to have
        # exceptions on the region, which would leave the lane with no
        # obstruction at all once E dies
        claims["c_branch_universal"] = False
    elif mutation == "claim_e_mechanism_structural":
        # THE HEADLINE DENIED: the 8x4 traceless-corner mechanism asserted to
        # scale, which the T_phys = 6 and T_phys = 8 measurements forbid
        claims["e_mechanism_scales"] = True
    elif mutation == "break_wrap_theorem":
        # THE CHECKER'S DISCRIMINATOR DENIED: free-link leakage asserted at
        # T_phys = 8, where the congruence 2 = -2 is broken
        claims["leak_by_size"] = tuple(
            1 if tag == "16x4" else (1 if COLLAPSE[tag] else 0)
            for tag in TAGS
        )
    elif mutation == "claim_p5d_binding":
        # THE VACUITY SMOOTHED: the containment gate asserted to be binding at
        # every size, which the mod-4 residue count denies
        claims["p5d_binding_everywhere"] = True
    elif mutation == "claim_164_needs_correction":
        # THE ADJUDICATION REVERSED: Block 164 asserted to owe a
        # correction-in-successor, which its own landed two-branch fence denies
        claims["b164_correction_required"] = True
    elif mutation == "drop_checker_t8_credit":
        # the T_phys = 8 discriminator stripped of its checker attribution
        claims["required_scope_keys"] = tuple(
            key for key in SCOPE_KEYS
            if key not in ("t_eight_discriminator", "confounds_excluded",
                           "checker_credit", "checker_reproduction",
                           "three_points")
        )
    elif mutation == "drop_n5_fence":
        claims["required_scope_keys"] = tuple(
            key for key in SCOPE_KEYS if key != "n5_verbatim"
        )
    return claims


# ---------------------------------------------------------------------------
# gates: pure functions of the measured facts and the claims
# ---------------------------------------------------------------------------
def evaluate_gates(facts: Facts, claims: dict, elapsed_ns: int) -> dict:
    authority = facts.authority
    parent_blobs_ok = (
        authority.parent_artifact_blobs
        if claims["parent_pin"] == "resolved"
        else authority.stale_parent_artifact_blobs
    )
    gate_a = bool(
        AUDIT_INPUT_PATHS
        == (
            "docs/ADMISSIBILITY_DIRAC_KAHLER_SCALING_PROBE_BOUNDED_THEOREM_NOTE_2026-08-21.md",
            "docs/MINIMAL_AXIOMS_2026-06-29.md",
            "docs/audit/data/axiom_premise_nodes.json",
            "docs/ADMISSIBILITY_DIRAC_KAHLER_ZERO_SHEAR_REGION_BOUNDED_THEOREM_NOTE_2026-08-21.md",
            "scripts/admissibility_dirac_kahler_zero_shear_region_2026_08_21.py",
        )
        and PARENT_ARTIFACTS == (BLOCK164_NOTE, BLOCK164_RUNNER)
        and len(PARENT_ARTIFACT_BLOBS) == len(PARENT_ARTIFACTS) == 2
        and facts.main_head == claims["main_head"]
        and authority.fixed_authority
        and authority.parent_pin_is_commit
        and authority.parent_ref_and_ancestry
        and parent_blobs_ok
    )

    passing, total = facts.anchors[0], facts.anchors[1]
    space_obstruction = not all(facts.anchors[2])
    gate_b = bool(
        total == ANCHOR_COUNT
        and passing == claims["anchors_passing"]
        and space_obstruction == claims["space_obstruction"]
        and facts.anchors[3] == tuple(INVOLUTIVE_COUNTS[tag] for tag in TAGS)
        and facts.anchors[4] == tuple(X_TRIVIAL_COUNTS[tag] for tag in TAGS)
        and all(facts.anchors[5])
        and all(count >= BASELINE_EDGES for count in facts.anchors[6])
        and (not facts.deep
             or all(count == EDGE_COUNT for count in facts.anchors[6]))
        and facts.exact_no_float
    )

    grading_is_universal = bool(
        all(facts.grading[0])
        and all(seen == used for seen, used in facts.grading[1])
        and all(seen == total_labels for seen, total_labels in facts.grading[2])
    )
    gate_c = bool(
        grading_is_universal == claims["grading_is_universal"]
        and all(facts.grading[4])
        and not any(facts.grading[5])
        and all(facts.grading[6])
        and all(facts.grading[7])
        and facts.grading[3]["8x4"] == (0, 1, 3)
        and facts.grading[3]["12x4"] == (0, 1, 5)
        and facts.grading[3]["8x6"] == (0, 1, 3)
        and facts.grading[3]["16x4"] == (0, 1, 7)
        and facts.exact_no_float
    )

    measured_dims = tuple(facts.law[7][tag] for tag in TAGS)
    codimension_derived = all(
        facts.law[5][tag] - facts.law[7][tag] == REGION_CODIM[tag]
        and facts.law[6][tag] == REGION_CODIM[tag]
        for tag in TAGS
    )
    law_holds = all(
        facts.law[7][tag] == 2 * lx * (cover_t // 2 - 1)
        for tag, cover_t, lx in FIXTURE_SPECS
    )
    law_is_a_fit = not (
        codimension_derived
        and law_holds
        and all(facts.law[9])
        and facts.law[12] >= LAW_POINTS
    )
    gate_d = bool(
        all(hit == cells for hit, cells in facts.law[0])
        and all(hit == cells for hit, cells in facts.law[1])
        and all(hit == cells for hit, cells in facts.law[2])
        and all(hit == cells for hit, cells in facts.law[3])
        and all(slots == traceless == massive and slots > 0
                for slots, traceless, massive in facts.law[4])
        and facts.law[5] == AMBIENT_COORDS
        and facts.law[6] == REGION_CODIM
        and measured_dims == claims["region_dims"]
        and law_is_a_fit == claims["law_is_a_fit"]
        and facts.law[8] == tuple(REGION_CODIM[tag] for tag in TAGS)
        and all(facts.law[9])
        and all(hit == used for hit, used in facts.law[10])
        and all(hit == used for hit, used in facts.law[11])
        and all(free_only for free_only, _width in facts.law[13])
        and all(
            cells == agree and disagree == 0 and psd > 0
            for cells, agree, disagree, psd in facts.law[14]
        )
        and all(
            cells == carriers * bench_edges * masses * involutions
            for (cells, _a, _d, _p), (carriers, bench_edges, masses,
                                      involutions)
            in zip(facts.law[14], facts.law[15])
        )
        and (not facts.deep
             or tuple(hit for hit, _cells in facts.law[0])
             == tuple(DEEP_HOLLOW_CELLS[tag] for tag in TAGS))
        and facts.exact_no_float
    )

    max_st_degree = max(facts.branch[1])
    c_branch_universal = all(live == cells for live, cells in facts.branch[2])
    gate_e = bool(
        all(hit == entries and entries > 0
            for hit, entries in facts.branch[0])
        and max_st_degree == claims["max_st_degree"]
        and c_branch_universal == claims["c_branch_universal"]
        and all(
            psd == zero_cells and not_psd == st_cells and zero_cells > 0
            for psd, zero_cells, not_psd, st_cells in facts.branch[4]
        )
        and tuple(rank for rank in facts.branch[5])
        == tuple((spec[2],) for spec in FIXTURE_SPECS)
        and facts.branch[6] == INERTIA_SELF_TESTS
        and facts.exact_no_float
    )

    e_mechanism_scales = all(live > 0 for live, _cells in facts.wrap[3])
    leak_pattern = tuple(
        1 if leak > 0 else 0 for leak, _pairs in facts.wrap[1]
    )
    gate_f = bool(
        facts.wrap[0] == tuple(COLLAPSE[tag] for tag in TAGS)
        and leak_pattern == claims["leak_by_size"]
        and all(
            (leak == pairs) if COLLAPSE[tag] else (leak == 0)
            for tag, (leak, pairs) in zip(TAGS, facts.wrap[1])
        )
        and e_mechanism_scales == claims["e_mechanism_scales"]
        and all(
            (live > 0) == bool(E_LIVE_RATE[tag])
            for tag, (live, _cells) in zip(TAGS, facts.wrap[3])
        )
        and all(hit == cells for hit, cells in facts.wrap[4])
        and all(hit == cells for hit, cells in facts.wrap[5])
        and all(
            (live > 0) == bool(E_LIVE_RATE[tag])
            for tag, (live, _cells) in zip(TAGS, facts.wrap[6])
        )
        # THE CONTENT LAW at exact equality is a --deep claim, and the reason is
        # disclosed: a low-sample edge set UNDERSTATES its own mechanism (the
        # checker's objection to the solve's single-edge print), so at baseline
        # only the CONTAINMENT in the pinned links is gated -- which is the
        # leakage measurement above -- and the exact content {c-1, c} is gated
        # when every healed edge has been swept.
        and (not facts.deep
             or (all(
                 facts.wrap[2][tag][cc] == tuple(sorted(
                     {(cc - 1) % (cover_t // 2), cc % (cover_t // 2)}
                 ))
                 for tag, cover_t, _lx in FIXTURE_SPECS if not COLLAPSE[tag]
                 for cc in facts.wrap[2][tag]
             )
                 and tuple(live for live, _c in facts.wrap[3])
                 == tuple(DEEP_E_LIVE[tag] for tag in TAGS)
                 and tuple(cells for _l, cells in facts.wrap[3])
                 == tuple(DEEP_E_CELLS[tag] for tag in TAGS)
                 and tuple(live for live, _c in facts.wrap[6])
                 == tuple(DEEP_NONXT_LIVE[tag] for tag in TAGS)
                 and tuple(cells for _l, cells in facts.wrap[6])
                 == tuple(DEEP_NONXT_CELLS[tag] for tag in TAGS)
                 and tuple(leak for leak, _p in facts.wrap[1])
                 == tuple(DEEP_LEAK[tag] for tag in TAGS)
                 and tuple(pairs for _l, pairs in facts.wrap[1])
                 == tuple(DEEP_LEAK_PAIRS[tag] for tag in TAGS)))
        and facts.exact_no_float
    )

    p5d_binding_everywhere = not any(facts.parity[3])
    gate_g = bool(
        all(hit == expected and expected > 0
            for hit, expected in facts.parity[0])
        and all(hit == expected for hit, expected in facts.parity[1])
        and all(hit == pairs for hit, pairs in facts.parity[2])
        and facts.parity[3] == tuple(COLLAPSE[tag] for tag in TAGS)
        and p5d_binding_everywhere == claims["p5d_binding_everywhere"]
    )

    required = tuple(claims["required_scope_keys"])
    correction_required = not facts.b164_already_scoped
    budget = DEEP_RUNTIME_BUDGET_SEC if facts.deep else RUNTIME_BUDGET_SEC
    gate_h = bool(
        set(facts.scope) == set(required)
        and all(facts.scope.values())
        and correction_required == claims["b164_correction_required"]
        and len(MUTATIONS) == 15
        and len(set(MUTATIONS)) == 15
        and set(MUTATION_GATE) == set(MUTATIONS)
        and set(MUTATION_GATE.values()) == set("ABCDEFGH")
        and N5_FENCE.count("\n") + 1 <= 10
        and N5_FENCE.count("\n") + 1 >= 8
        and POOL_TWO_LEADS == 4
        and elapsed_ns <= budget * 1_000_000_000
    )

    return {
        "A": gate_a,
        "B": gate_b,
        "C": gate_c,
        "D": gate_d,
        "E": gate_e,
        "F": gate_f,
        "G": gate_g,
        "H": gate_h,
    }


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--mutation", choices=MUTATIONS, default="")
    parser.add_argument(
        "--deep",
        action="store_true",
        help="all 16 healed edges at every fixture; the baseline runs a "
             "disclosed SAMPLE and the census constants are gated only here",
    )
    arguments = parser.parse_args()
    mutation = arguments.mutation
    started_ns = time.monotonic_ns()

    # Every measurement happens once, before any mutation flag is consulted, so
    # a mutation can only rewrite a CLAIM.  No gate can cascade into another
    # because no gate feeds a measurement.
    facts = measure(arguments.deep)
    elapsed_ns = time.monotonic_ns() - started_ns

    raw_gates = evaluate_gates(facts, build_claims(""), elapsed_ns)
    gate_values = dict(raw_gates)
    if mutation:
        target = MUTATION_GATE[mutation]
        gate_values = evaluate_gates(
            facts, build_claims(mutation), elapsed_ns
        )
        changed = {
            key for key in raw_gates if raw_gates[key] != gate_values[key]
        }
        if changed - {target} or gate_values[target]:
            raise AssertionError("mutation did not fail exactly its own gate")

    print("MEASURED, before any gate is read:")
